-- XTCW widget reference browser.
--
-- Data source: build/doc/hdf/*.hdf (generated by wbuild).  HDF carries the
-- superclass chain, resource/method/action anchors, owner/inherited flags and
-- inline description links.  Wmarkdown renders the page and reports link
-- activations; the browser resolves the anchor and keeps a back/forward
-- history.
--
-- Run:
--   ./run_lui.sh tools/widget_help.lua
--   lua5.3 tools/widget_help.lua --self-test

local function script_root()
    local src = debug.getinfo(1, "S").source or ""
    src = src:gsub("^@", "")
    local root = src:match("^(.*)/tools/[^/]+$")
    if root and root ~= "" then return root end
    if src:match("^tools/[^/]+$") then return "." end
    return os.getenv("XTCW_ROOT") or ".."
end

local ROOT = script_root()
local DOCDIR = ROOT .. "/build/doc"
local HDFDIR = DOCDIR .. "/hdf"

package.path = ROOT .. "/tools/?.lua;" .. package.path
local hdf = require("hdf")

-- ------------------------------------------------------------- data model --

local docs = {}
local by_name = {}
local anchors = {}

local function add_anchor(anchor, kind, doc, item)
    if anchor and anchor ~= "" then
        anchors[anchor] = { kind = kind, doc = doc, item = item }
    end
end

local function load_docs()
    local files = {}
    local p = io.popen("ls -1 '" .. HDFDIR:gsub("'", "'\\''") .. "' 2>/dev/null")
    if not p then return end
    for file in p:lines() do
        if file:match("%.hdf$") then files[#files + 1] = file end
    end
    p:close()

    for _, file in ipairs(files) do
        local ok, h = pcall(hdf.load, HDFDIR .. "/" .. file)
        if not ok then
            io.stderr:write("widget_help: " .. tostring(h) .. "\n")
            h = nil
        end
        if h and h.kind == "widget" and h.class then
            local d = {
                name = h.class,
                anchor = h.anchor,
                hdf = h,
                superclass = h.superclass,
                superclass_chain = h.superclass_chain or {},
                resources = h.resources or {},
                methods = h.methods or {},
                utilities = h.utilities or {},
                actions = h.actions or {},
                translations = h.translations or {},
                exports = h.exports or {},
                classvars = h.classvars or {},
            }
            docs[#docs + 1] = d
            by_name[d.name] = d
            add_anchor(d.anchor, "widget", d)

            for _, r in ipairs(d.resources) do add_anchor(r.anchor, "resource", d, r) end
            for _, m in ipairs(d.methods) do add_anchor(m.anchor, "method", d, m) end
            for _, u in ipairs(d.utilities) do add_anchor(u.anchor, "utility", d, u) end
            for _, a in ipairs(d.actions) do add_anchor(a.anchor, "action", d, a) end
        end
    end

    table.sort(docs, function(a, b) return a.name < b.name end)
end

-- -------------------------------------------------------------- markdown ----

local function code(s)
    if s == nil or s == "" then return "``" end
    return "`" .. tostring(s) .. "`"
end

local function md_link(label, target)
    if target and target ~= "" then
        return "[" .. label .. "](" .. target .. ")"
    end
    return label
end

-- Replace |symbol| spans recorded by wbuild with Markdown links.
local function desc_md(item)
    local text = item.description or ""
    local links = item.description_links
    if not links or #links == 0 then return text end
    table.sort(links, function(a, b)
        return (tonumber(a.start) or 0) < (tonumber(b.start) or 0)
    end)
    local out = {}
    local pos = 1
    for _, l in ipairs(links) do
        local s = (tonumber(l.start) or 0) + 1
        local e = tonumber(l["end"]) or 0
        if s >= pos and e >= s then
            out[#out + 1] = text:sub(pos, s - 1)
            out[#out + 1] = md_link(l.label or "", l.target)
            pos = e + 1
        end
    end
    out[#out + 1] = text:sub(pos)
    return table.concat(out)
end

local function add_meta(out, item)
    local meta = {}
    if item.type and item.type ~= "" then
        meta[#meta + 1] = "type " .. code(item.type)
    end
    if item.default ~= nil and item.default ~= "" then
        meta[#meta + 1] = "default " .. code(item.default)
    end
    if item.owner and item.owner ~= "" then
        meta[#meta + 1] = "owner " .. md_link(item.owner, item.owner_link)
    end
    if item.inherited then meta[#meta + 1] = "inherited" end
    if item.constraint then meta[#meta + 1] = "constraint" end
    if #meta > 0 then
        out[#out + 1] = table.concat(meta, " · ")
        out[#out + 1] = ""
    end
end

local function render_widget(d)
    local out = { "# " .. d.name, "" }
    if d.hdf and d.hdf.description and d.hdf.description ~= "" then
        out[#out + 1] = desc_md(d.hdf)
        out[#out + 1] = ""
    end

    if d.superclass and d.superclass ~= "" then
        local chain = {}
        for _, ref in ipairs(d.superclass_chain) do
            chain[#chain + 1] = md_link(ref.class, ref.anchor)
        end
        if #chain == 0 then
            chain[1] = md_link(d.superclass, "widget/" .. d.superclass)
        end
        out[#out + 1] = "**Superclass:** " .. table.concat(chain, " > ")
        out[#out + 1] = ""
    end

    out[#out + 1] = string.format("## Resources (%d)", #d.resources)
    out[#out + 1] = ""
    for _, r in ipairs(d.resources) do
        out[#out + 1] = "### " .. md_link(code(r.name), r.anchor)
        add_meta(out, r)
        local text = desc_md(r)
        if text ~= "" then out[#out + 1] = text; out[#out + 1] = "" end
    end

    if #d.methods > 0 then
        out[#out + 1] = string.format("## Methods (%d)", #d.methods)
        out[#out + 1] = ""
        for _, m in ipairs(d.methods) do
            out[#out + 1] = "### " .. md_link(code(m.name), m.anchor)
            if m.signature and m.signature ~= "" then
                out[#out + 1] = ""; out[#out + 1] = code(m.signature)
            end
            local text = desc_md(m)
            if text ~= "" then out[#out + 1] = ""; out[#out + 1] = text end
            out[#out + 1] = ""
        end
    end

    if #d.utilities > 0 then
        out[#out + 1] = string.format("## Utilities (%d)", #d.utilities)
        out[#out + 1] = ""
        for _, u in ipairs(d.utilities) do
            out[#out + 1] = "### " .. md_link(code(u.name), u.anchor)
            if u.signature and u.signature ~= "" then
                out[#out + 1] = ""; out[#out + 1] = code(u.signature)
            end
            local text = desc_md(u)
            if text ~= "" then out[#out + 1] = ""; out[#out + 1] = text end
            out[#out + 1] = ""
        end
    end

    if #d.actions > 0 then
        out[#out + 1] = string.format("## Actions (%d)", #d.actions)
        out[#out + 1] = ""
        for _, a in ipairs(d.actions) do
            out[#out + 1] = "### " .. md_link(code(a.name), a.anchor)
            local text = desc_md(a)
            if text ~= "" then out[#out + 1] = ""; out[#out + 1] = text end
            out[#out + 1] = ""
        end
    end

    if #d.translations > 0 then
        out[#out + 1] = string.format("## Translations (%d)", #d.translations)
        out[#out + 1] = ""
        for _, t in ipairs(d.translations) do
            out[#out + 1] = "- " .. code(t.event or "") .. " -> " ..
                            md_link(t.action or "", t.action_link)
        end
        out[#out + 1] = ""
    end

    return table.concat(out, "\n")
end

local function render_resource(d, r)
    local out = { "# " .. code(r.name), "" }
    out[#out + 1] = "**Widget:** " .. md_link(d.name, d.anchor)
    if r.owner and r.owner ~= "" then
        out[#out + 1] = "**Owner:** " .. md_link(r.owner, r.owner_link)
    end
    out[#out + 1] = "**Anchor:** " .. code(r.anchor or "")
    out[#out + 1] = ""
    add_meta(out, r)
    local text = desc_md(r)
    if text ~= "" then out[#out + 1] = text; out[#out + 1] = "" end
    return table.concat(out, "\n")
end

local function render_callable(d, item, kind)
    local out = { "# " .. code(item.name), "" }
    out[#out + 1] = "**Widget:** " .. md_link(d.name, d.anchor)
    out[#out + 1] = "**Kind:** " .. kind
    if item.return_type and item.return_type ~= "" then
        out[#out + 1] = "**Return type:** " .. code(item.return_type)
    end
    out[#out + 1] = "**Anchor:** " .. code(item.anchor or "")
    out[#out + 1] = ""
    if item.signature and item.signature ~= "" then
        out[#out + 1] = code(item.signature)
        out[#out + 1] = ""
    end
    local text = desc_md(item)
    if text ~= "" then out[#out + 1] = text; out[#out + 1] = "" end
    return table.concat(out, "\n")
end

local function render_overview()
    local out = { "# XTCW widget reference", "",
                  string.format("%d widgets generated by wbuild. Select one in the list.",
                                #docs), "" }
    for _, d in ipairs(docs) do
        local desc = d.hdf and desc_md(d.hdf) or ""
        desc = desc:match("^[^\n]*") or ""
        out[#out + 1] = "- " .. md_link("**" .. d.name .. "**", d.anchor) ..
                        (desc ~= "" and (" — " .. desc) or "")
    end
    out[#out + 1] = ""
    return table.concat(out, "\n")
end

local function render_anchor(anchor)
    if anchor == "index" or anchor == "" or anchor == nil then
        return render_overview(), string.format("%d widgets", #docs)
    end
    local a = anchors[anchor]
    if not a then
        return "# Anchor not found\n\n" .. code(anchor), anchor
    end
    if a.kind == "widget" then
        return render_widget(a.doc), a.doc.name
    elseif a.kind == "resource" then
        return render_resource(a.doc, a.item), a.item.name
    elseif a.kind == "method" then
        return render_callable(a.doc, a.item, "method"), a.item.name
    elseif a.kind == "utility" then
        return render_callable(a.doc, a.item, "utility"), a.item.name
    elseif a.kind == "action" then
        return render_callable(a.doc, a.item, "action"), a.item.name
    end
    return "# Unknown anchor\n\n" .. code(anchor), anchor
end

-- -------------------------------------------------------------- self-test --

load_docs()

if arg and arg[1] == "--self-test" then
    assert(#docs > 0, "no HDF docs found in " .. HDFDIR .. " (run make widgets)")
    assert(by_name["WAudioChassis"], "WAudioChassis HDF missing")
    local md = render_widget(by_name["WAudioChassis"])
    assert(md:match("## Resources"), "resource section missing")
    assert(md:match("## Methods"), "method section missing")
    assert(md:match("widget/Board"), "superclass link missing")
    assert(md:match("resource/Board/XtNabs_x"), "inherited resource anchor missing")
    assert(anchors["resource/WAudioChassis/XtNchassisWidth"], "resource anchor missing")
    local eq = render_widget(by_name["EqFader"])
    assert(eq:find(" -> ", 1, true), "translation arrow missing")
    assert(not eq:find("→", 1, true), "non-rendering Unicode arrow present")
    print(string.format("widget_help self-test: %d widgets, %d anchors",
                        #docs, (function()
                            local n = 0
                            for _ in pairs(anchors) do n = n + 1 end
                            return n
                        end)()))
    os.exit(0)
end

-- ------------------------------------------------------------------- gui ----

local gui = require('gui_xt')
local lui = require('lui')

local filtered = {}
local ready = false
local history = {}
local hist_pos = 0

local function set_view(md, status)
    gui.set("viewer", "text", md)
    gui.set("status", "label", status or "")
end

local function navigate(anchor, push)
    if push ~= false then
        for i = #history, hist_pos + 1, -1 do table.remove(history, i) end
        history[#history + 1] = anchor
        hist_pos = #history
    end
    local md, status = render_anchor(anchor)
    set_view(md, status)
end

local function back()
    if hist_pos > 1 then
        hist_pos = hist_pos - 1
        navigate(history[hist_pos], false)
    end
end

local function forward()
    if hist_pos < #history then
        hist_pos = hist_pos + 1
        navigate(history[hist_pos], false)
    end
end

local function home()
    navigate("index")
end

local function widget_row(d)
    return string.format("%s\t%d", d.name, #d.resources)
end

local function refresh_list()
    local rows = {}
    for _, d in ipairs(filtered) do rows[#rows + 1] = widget_row(d) end
    gui.set_string_list("list", "rows", rows)
    gui.set("status", "label", string.format("%d of %d widgets", #filtered, #docs))
    if #filtered == 0 then
        gui.set("viewer", "text", "# No matches\n\nTry a different search term.")
    end
end

function on_select()
    local sel = tonumber(gui.get("list", "selected")) or -1
    if sel < 0 or sel >= #filtered then return end
    navigate("widget/" .. filtered[sel + 1].name)
end

function on_search_changed()
    if not ready then return end
    local q = tostring(gui.get("search", "label") or ""):lower()
    filtered = {}
    for _, d in ipairs(docs) do
        local hay = (d.name .. " " .. ((d.hdf and d.hdf.description) or "")):lower()
        if q == "" or hay:find(q, 1, true) then
            filtered[#filtered + 1] = d
        end
    end
    refresh_list()
    if #filtered > 0 then
        gui.set("list", "selected", 0)
        on_select()
    end
end

function on_link()
    local target = gui.get("viewer", "lastLink")
    if target and target ~= "" then navigate(target) end
end

function on_home() home() end
function on_back() back() end
function on_forward() forward() end
function on_overview() home() end

for _, d in ipairs(docs) do filtered[#filtered + 1] = d end

local ui = [[
(window :id "win" :title "XTCW Widget Reference" :width 1180 :height 780
  (grid :id "main" :weightx 1 :weighty 1 :defaultDistance 8
    (label :id "title" :label "XTCW Widget Reference"
           :gridx 0 :gridy 0 :gridWidth 4 :weightx 1 :weighty 0 :fill 3
           :fontSize 18)
    (label :id "search_lbl" :label "Search:"
           :gridx 0 :gridy 1 :weightx 0 :weighty 0 :fill 3)
    (WLineEdit :id "search" :label "" :placeholder "Filter widgets by name or description..."
               :gridx 1 :gridy 1 :gridWidth 2 :weightx 1 :weighty 0 :fill 3
               :showClear TRUE
               :changed "LUA(on_search_changed)"
               :callback "LUA(on_search_changed)")
    (Wbutton :id "home" :label "Home"
             :gridx 3 :gridy 1 :weightx 0 :weighty 0 :fill 3
             :callback "LUA(on_home)")
    (Wbutton :id "back" :label "Back"
             :gridx 0 :gridy 2 :weightx 0 :weighty 0 :fill 3
             :callback "LUA(on_back)")
    (Wbutton :id "forward" :label "Forward"
             :gridx 1 :gridy 2 :weightx 0 :weighty 0 :fill 3
             :callback "LUA(on_forward)")
    (Wbutton :id "overview" :label "Overview"
             :gridx 2 :gridy 2 :weightx 0 :weighty 0 :fill 3
             :callback "LUA(on_overview)")
    (label :id "status" :label "Loading widget reference..."
           :gridx 3 :gridy 2 :weightx 1 :weighty 0 :fill 3)
    (WListView :id "list"
               :gridx 0 :gridy 3 :width 300 :weightx 0 :weighty 1 :fill 3
