               :showHeader 1 :gridLines 1 :alternateRows 1
               :visibleRows 22
               :on-row-activated "LUA(on_select)"
               :on-activate "LUA(on_select)")
    (Wmarkdown :id "viewer"
               :gridx 1 :gridy 3 :gridWidth 3 :weightx 1 :weighty 1 :fill 3
